import React, { type MutableRefObject, type ReactElement } from 'react';
import { differenceWith, isEqual, concat, difference, isEmpty, isArray } from 'lodash';
import type { ItemValue, Values } from '@fiverr-private/dropdown';
import type { MenuItemElement, MenuItemExpanded } from '../../types';

const getSelectedItemsProps = (
    menuGroup: ReactElement,
    groupSelectedValues: ItemValue | ItemValue[]
): MenuItemExpanded[] => {
    const { children: menuItems, name } = menuGroup.props;
    const selectedValuesProps: MenuItemExpanded[] = [];

    if (isArray(groupSelectedValues)) {
        groupSelectedValues.forEach((value: ItemValue) => {
            let valueFound = false;
            React.Children.forEach(menuItems, (child: MenuItemElement) => {
                if (child.props.value === value) {
                    selectedValuesProps.push({ ...child.props, groupName: name });
                    valueFound = true;
                }
            });

            if (!valueFound) {
                selectedValuesProps.push({
                    groupName: name,
                    children: value,
                    value,
                });
            }
        });
    } else {
        React.Children.forEach(menuItems, (child: ReactElement) => {
            if (child.props.value === groupSelectedValues) {
                selectedValuesProps.push({ ...child.props, groupName: name });
            }
        });
    }

    return selectedValuesProps;
};

const getSelectedItems = (values: Values, menuGroups: ReactElement[]) => {
    let valuesArray: ReactElement['props'][] = [];
    Object.keys(values).forEach((value) => {
        const menuGroup = menuGroups?.find((menuGroup) => menuGroup.props.name === value);

        if (!isEmpty(menuGroup)) {
            const filteredValues = getSelectedItemsProps(menuGroup, values[value]);
            if (!isEmpty(filteredValues)) {
                valuesArray = [...valuesArray, ...filteredValues];
            }
        }
    });

    return valuesArray;
};

export const getUpdatedSelectedItems = (
    prevSelectedValues: MutableRefObject<Values>,
    newSelectedValues: Values,
    children: ReactElement | ReactElement[]
): MenuItemExpanded[] => {
    const prevSelectedItems = Object.values(
        getSelectedItems(prevSelectedValues.current, React.Children.toArray(children) as ReactElement[])
    ).flatMap((item) => item);
    const newSelectedItems = Object.values(
        getSelectedItems(newSelectedValues, React.Children.toArray(children) as ReactElement[])
    ).flatMap((item) => item);
    const removedItems = differenceWith(prevSelectedItems, newSelectedItems, isEqual);
    const addedItems = differenceWith(newSelectedItems, prevSelectedItems, isEqual);
    const selectedItems = concat(prevSelectedItems, addedItems);

    prevSelectedValues.current = newSelectedValues;

    return difference(selectedItems, removedItems);
};
