import React, { useEffect } from 'react';
import { isNil } from 'lodash';
import { DropdownMenu, focusContent, useDropdownContext } from '@fiverr-private/dropdown';
import { Center } from '@fiverr-private/layout_components';
import { Text } from '@fiverr-private/typography';
import useComboboxContext from '../hooks/useComboboxContext';
import { ComboboxProps } from '../types';
import { getFilteredChildren } from '../utils';

interface ComboboxOptionsProps {
  children: ReturnType<typeof getFilteredChildren>;
  copies: ComboboxProps['copies'];
}

const ComboboxOptions = ({ children, copies }: ComboboxOptionsProps) => {
  const { items, setFocusedItem, isMultiSelect, values } = useDropdownContext();
  const { isInitialMultiSelect } = useComboboxContext();

  if (isNil(isInitialMultiSelect.current) && isMultiSelect.current) {
    isInitialMultiSelect.current = true;
  }

  useEffect(() => {
    focusContent({ items, setFocusedItem, values });
  }, [items, setFocusedItem, values, children]);

  return (
    <DropdownMenu>
      {children || (
        <Center>
          <Text>{copies?.noOptionsText()}</Text>
        </Center>
      )}
    </DropdownMenu>
  );
};

export default ComboboxOptions;
