import { useCallback, useMemo, useRef, useState, useEffect, type ReactElement } from 'react';
import { isEqual, isUndefined } from 'lodash';
import type { Values } from '@fiverr-private/dropdown';
import { filterChildrenByType } from '@fiverr-private/ui_utils';
import { getFilteredChildren } from '../../utils';
import type { IComboboxContext } from '../useComboboxContext';
import { MENU_GROUP_ID } from '../../constants';
import type { ComboboxProps } from '../../types';
import { getUpdatedSelectedItems } from './utils';

const useComboboxState = ({
  children,
  value,
  defaultValue = {},
  onChange,
  onInputValueChange,
  inputValue,
  theme,
}: Partial<ComboboxProps>): IComboboxContext => {
  const [searchValue, setSearchValue] = useState<string | undefined>();
  const [currentFocusedElement, setCurrentFocusedElement] = useState<HTMLElement | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const prevSelectedValues = useRef<Values>({});
  const isInitialMultiSelect = useRef<boolean>(null);
  const shouldFilterItems = useRef<boolean>(true);
  const controlled = !isUndefined(value);
  const [innerValue, setInnerValue] = useState<Values>(controlled ? value : defaultValue);
  const effectiveSearchValue = !isUndefined(inputValue) ? inputValue : searchValue;

  useEffect(() => {
    if (controlled && !isEqual(innerValue, value)) {
      setInnerValue(value);
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [controlled, value]);

  const handleChange = useCallback(
    (newValues: Values) => {
      if (controlled) {
        onChange?.(newValues);
        return;
      }

      setInnerValue(newValues);
      onChange?.(newValues);
    },
    [onChange, controlled]
  );

  const handleSearchValueChange = useCallback(
    (newValue) => {
      setSearchValue(newValue);
      onInputValueChange?.(newValue);
    },
    [setSearchValue, onInputValueChange]
  );

  const filteredMenuGroups = useMemo(
    () =>
      getFilteredChildren(
        innerValue,
        children as ReactElement | ReactElement[],
        effectiveSearchValue,
        shouldFilterItems
      ),
    [children, effectiveSearchValue, innerValue]
  );
  const updatedSelectedItems = useMemo(
    () => getUpdatedSelectedItems(prevSelectedValues, innerValue, children as ReactElement | ReactElement[]),
    [children, innerValue]
  );
  const hasMultipleGroups = useMemo(() => filterChildrenByType(children, MENU_GROUP_ID).length > 1, [children]);

  return {
    innerValue,
    setInnerValue: handleChange,
    searchValue: effectiveSearchValue,
    setSearchValue: handleSearchValueChange,
    currentFocusedElement,
    setCurrentFocusedElement,
    inputRef,
    isInitialMultiSelect,
    shouldFilterItems,
    filteredMenuGroups,
    updatedSelectedItems,
    controlled,
    hasMultipleGroups,
    theme: theme || 'light',
  };
};

export default useComboboxState;
