import React, { ReactElement } from 'react';
import { isEmpty, isString } from 'lodash';
import { findChildByType, childrenIdMatch } from '@fiverr-private/ui_utils';
import type { ItemValue, Values } from '@fiverr-private/dropdown';
import { MENU_GROUP_ID, OPTION_LABEL_ID } from './constants';
import type { FilterMenuItems, MenuGroupElement, MenuItemElement } from './types';
import type { ComboboxOptionProps } from './ComboboxOption/types';
import type { ComboboxOptionLabelProps } from './ComboboxOption/ComboboxOptionLabel/types';

export const getSelectedItemByText = (menuItems, groupSelectedValues) => {
    let selectedItemProps: string | undefined;

    if (!groupSelectedValues) {
        return selectedItemProps;
    }

    React.Children.forEach(menuItems, (child) => {
        if ((child as MenuItemElement).props.value?.toString() === groupSelectedValues.item) {
            selectedItemProps = getOptionText(child.props.children);
        }
    });

    return selectedItemProps;
};

export const getOptionText = (children: ComboboxOptionProps['children']): string => {
    let optionLabel: ReactElement<ComboboxOptionLabelProps> | null = null;
    let searchText = '';

    if (children) {
        if (isString(children)) {
            return children;
        }

        for (const child of React.Children.toArray(children) as ReactElement[]) {
            if (child?.props?.children) {
                optionLabel = findChildByType(
                    child.props.children,
                    OPTION_LABEL_ID
                ) as ReactElement<ComboboxOptionLabelProps>;
                if (optionLabel) {
                    return optionLabel.props.children;
                } else {
                    searchText = getOptionText(child.props.children);
                    if (searchText) {
                        return searchText;
                    }
                }
            }
        }
    }

    return searchText;
};

const isOptionCreate = (menuItem) => {
    const comboboxOptionCreate = childrenIdMatch(menuItem, 'ComboboxOptionCreate');
    return comboboxOptionCreate;
};
const filterMenuItems = ({
    menuItems,
    groupSelectedValues,
    searchValue = '',
    name = 'item',
    shouldFilterItem,
}: FilterMenuItems) => {
    let unselectedChildren = React.Children.toArray(menuItems) as ReactElement[];
    const shouldFilterSelectedItems = Array.isArray(menuItems) && Array.isArray(groupSelectedValues[name]);
    if (name === 'item' && groupSelectedValues[name] && shouldFilterItem?.current) {
        const selectedItemText = getSelectedItemByText(menuItems, groupSelectedValues);
        if (searchValue === selectedItemText) {
            shouldFilterItem.current = false;
            return menuItems;
        }
    }
    if (shouldFilterSelectedItems) {
        unselectedChildren = (React.Children.toArray(menuItems) as ReactElement[]).filter(
            (menuItem) =>
                !(
                    (groupSelectedValues[name] as ItemValue[])?.includes(menuItem?.props?.value) ||
                    (isOptionCreate(menuItem) && !searchValue)
                )
        );
    }
    if (searchValue) {
        const searchedItems = unselectedChildren.filter((menuItem) => {
            const optionCreate = isOptionCreate(menuItem);
            if (optionCreate && shouldFilterItem) {
                shouldFilterItem.current = false;
            }
            return (
                getOptionText(menuItem?.props?.children)
                    ?.toLocaleLowerCase()
                    .includes(searchValue.trim().toLocaleLowerCase()) || optionCreate
            );
        });
        if (isEmpty(searchedItems)) {
            return null;
        }

        return searchedItems;
    }
    if (isEmpty(unselectedChildren)) {
        return null;
    }

    if (shouldFilterSelectedItems) {
        return unselectedChildren;
    }

    return menuItems;
};

const filteredMenuGroup = (
    menuGroup: ReactElement,
    groupSelectedValues: Values,
    searchValue = ''
): MenuGroupElement | null => {
    const { children: menuItems, name } = menuGroup.props;
    const filteredMenuItems = filterMenuItems({ menuItems, groupSelectedValues, searchValue, name });
    if (filteredMenuItems) {
        return React.cloneElement(menuGroup, {
            children: filteredMenuItems,
        });
    } else {
        return null;
    }
};

export const getFilteredMenuGroups = (
    values: Values,
    menuGroups: ReactElement | ReactElement[],
    searchValue = ''
): MenuGroupElement[] | null => {
    const childrenToRender: MenuGroupElement[] = [];
    const menuGroupsArray: MenuGroupElement[] = React.Children.toArray(menuGroups) as MenuGroupElement[];

    React.Children.forEach(menuGroupsArray, (menuGroup: ReactElement) => {
        const filteredMenuGroups = filteredMenuGroup(menuGroup, values, searchValue);
        if (filteredMenuGroups) {
            childrenToRender.push(filteredMenuGroups);
        }
    });
    if (!isEmpty(childrenToRender)) {
        return childrenToRender;
    } else {
        return null;
    }
};

export const getFilteredChildren = (
    values: Values,
    children: ReactElement | ReactElement[],
    searchValue = '',
    shouldFilterItem
) => {
    const hasMenuGroupChild = findChildByType(children, MENU_GROUP_ID);

    if (hasMenuGroupChild) {
        return getFilteredMenuGroups(values, children, searchValue);
    } else {
        return filterMenuItems({
            menuItems: children,
            groupSelectedValues: values,
            searchValue,
            shouldFilterItem,
        });
    }
};
