import React from 'react';
import { ChevronButton, TimesButton } from '@fiverr-private/button';
import { Center } from '@fiverr-private/layout_components';
import { usePopoverContext } from '@fiverr-private/popover';
import { translate } from '@fiverr-private/i18n-react';
import useComboboxContext from '../../hooks/useComboboxContext';

const ControlButtons = ({ showClearButton, disabled }: { showClearButton: boolean; disabled?: boolean }) => {
  const { setSearchValue, setInnerValue, theme } = useComboboxContext();
  const { open } = usePopoverContext();
  const isDark = theme === 'dark';

  return (
    <Center dataTrackTag="combobox_control_buttons" direction="row" flexShrink="0" gap="0.5">
      <TimesButton
        type="button"
        ariaLabel={translate<string>('forms.buttons.clear')}
        onClick={(e) => {
          setSearchValue('');
          setInnerValue({});
          e.stopPropagation();
        }}
        tabIndex={-1}
        visibility={showClearButton ? 'visible' : 'hidden'}
        size="3xs"
        theme={isDark ? 'light' : 'dark'}
        disabled={disabled}
      />
      <ChevronButton
        size="3xs"
        chevronDirection={open ? 'up' : undefined}
        disabled={disabled}
        theme={isDark ? 'light' : 'dark'}
      />
    </Center>
  );
};

export default ControlButtons;
