import { useEffect, useState } from 'react';
import { isEmpty } from 'lodash';
import { usePopoverContext } from '@fiverr-private/popover';
import useComboboxContext from '../useComboboxContext';
import { TriggerProps } from '../../Trigger/types';

interface UseClearButton {
    showClearButton: boolean;
    onMouseEnter?: () => void;
    onMouseLeave?: () => void;
}

const useClearButton = (
    containerRef: React.RefObject<HTMLElement>,
    hideClearButton: TriggerProps['hideClearButton']
): UseClearButton => {
    const { currentFocusedElement, searchValue, innerValue } = useComboboxContext();
    const { open } = usePopoverContext();
    const [showClearButton, setShowClearButton] = useState(false);

    useEffect(() => {
        if (hideClearButton) {
            setShowClearButton(false);
        } else {
            if (
                containerRef.current &&
                currentFocusedElement &&
                !isEmpty(innerValue) &&
                containerRef.current?.contains(currentFocusedElement)
            ) {
                setShowClearButton(true);
            } else if (containerRef.current && !currentFocusedElement && !open) {
                setShowClearButton(false);
            }
            if (isEmpty(innerValue) && !searchValue?.length) {
                setShowClearButton(false);
            }
        }
    }, [
        currentFocusedElement,
        open,
        searchValue?.length,
        innerValue,
        containerRef,
        setShowClearButton,
        hideClearButton,
    ]);

    const onMouseEnter = () => {
        if (!isEmpty(innerValue) || searchValue?.length) {
            setShowClearButton(true);
        }
    };

    const onMouseLeave = () => {
        if (!currentFocusedElement) {
            setShowClearButton(false);
        }
    };

    return { showClearButton, ...(!hideClearButton ? { onMouseEnter, onMouseLeave } : {}) };
};
export default useClearButton;
