import React, { useEffect, useRef, useState } from 'react';
import { HighlightText, Text } from '@fiverr-private/typography';
import { OPTION_LABEL_ID } from '../../constants';
import useComboboxContext from '../../hooks/useComboboxContext';
import type { ComboboxOptionLabelProps } from './types';

const MIN_HEIGHT = 48;

const ComboboxOptionLabel = ({ children, isOptionCreate }: ComboboxOptionLabelProps) => {
  const { searchValue, theme } = useComboboxContext();
  const textRef = useRef<HTMLElement | null>(null);
  const [isMulti, setIsMulti] = useState(false);

  useEffect(() => {
    const checkHeight = () => {
      if (textRef.current) {
        const offsetHeight = textRef.current.offsetHeight;
        setIsMulti(offsetHeight > MIN_HEIGHT);
      }
    };

    checkHeight();
  }, [children]);

  return isOptionCreate ? (
    <Text ref={textRef} fontWeight="bold" marginLeft={isMulti ? '2' : '0'} wordBreak="breakAll">
      {children}
    </Text>
  ) : (
    <HighlightText as="span" query={searchValue} color={theme === 'dark' ? 'white' : undefined}>
      {children}
    </HighlightText>
  );
};

ComboboxOptionLabel.displayName = OPTION_LABEL_ID;
ComboboxOptionLabel.id = OPTION_LABEL_ID;

export default ComboboxOptionLabel;
