import { theme } from '@fiverr-private/theme';
import type { ComboboxProps } from '../types';

export const generateBorderFocusWithin = ({
    isError,
    isSuccess,
    isDark,
}: {
    isError: ComboboxProps['isError'];
    isSuccess: ComboboxProps['isSuccess'];
    isDark: boolean;
}) => {
    const { validationError, validationSuccess } = theme.semanticBorderColors;

    if (isDark) {
        return 'white_20';
    } else if (isError) {
        return validationError;
    } else if (isSuccess) {
        return validationSuccess;
    } else {
        return 'grey_1200';
    }
};
