import React, { forwardRef } from 'react';
import { Dropdown, DropdownContent } from '@fiverr-private/dropdown';
import { translate } from '@fiverr-private/i18n-react';
import Trigger from './Trigger';
import { ComboboxContext } from './hooks/useComboboxContext';
import type { ComboboxProps, ThemeType } from './types';
import ComboboxOptions from './ComboboxOptions';
import useComboboxState from './hooks/useComboboxState';

const Combobox = forwardRef<HTMLInputElement, ComboboxProps>(
  (
    {
      children,
      copies = {
        noOptionsText: () => translate('forms.combobox.noOptions'),
      },
      placeholder,
      isError,
      isSuccess,
      disabled,
      value,
      onChange,
      defaultValue,
      hideClearButton = false,
      onInputValueChange,
      isOpen,
      onOpenChanged,
      appendToBody,
      popoverPosition,
      disableFlip,
      inputValue,
      goExperimental = false,
      theme = 'light',
      dataTrackTag = 'combobox',
      dataTrackValue,
      ...rest
    }: ComboboxProps,
    ref
  ) => {
    const currentTheme: ThemeType | undefined = goExperimental ? 'dark' : theme;
    const state = useComboboxState({
      children,
      value,
      defaultValue,
      onChange,
      onInputValueChange,
      inputValue,
      theme: currentTheme,
    });

    return (
      <ComboboxContext.Provider value={state}>
        <Dropdown
          searchWhenClosed
          values={state.innerValue}
          onChange={state.setInnerValue}
          searchOnKeyPress={false}
          selectedIndicatorPosition="right"
          isOpen={isOpen}
          onOpenChanged={onOpenChanged}
          disableFlip={disableFlip}
          position={popoverPosition}
          theme={currentTheme}
        >
          <Trigger
            ref={ref}
            isError={isError}
            isSuccess={isSuccess}
            disabled={disabled}
            placeholder={placeholder}
            defaultValue={defaultValue}
            hideClearButton={hideClearButton}
            theme={currentTheme}
            dataTrackTag={dataTrackTag}
            dataTrackValue={dataTrackValue}
            {...rest}
          />
          <DropdownContent dataTrackTag="combobox_content" fullWidth disableExitAnimation appendToBody={appendToBody}>
            <ComboboxOptions copies={copies}>{state.filteredMenuGroups}</ComboboxOptions>
          </DropdownContent>
        </Dropdown>
      </ComboboxContext.Provider>
    );
  }
);

Combobox.displayName = 'Combobox';
export default Combobox;
