import React, { forwardRef, useEffect, useImperativeHandle, useRef, useMemo } from 'react';
import { isNil } from 'lodash';
import classNames from 'classnames';
import { Box, assignInlineVars, tokens, utilityClasses } from '@fiverr-private/theme';
import { DropdownAnchor } from '@fiverr-private/dropdown';
import { Stack } from '@fiverr-private/layout_components';
import { usePopoverContext } from '@fiverr-private/popover';
import { useInputTrackValue } from '@fiverr-private/inputs';
import useComboboxContext from '../hooks/useComboboxContext';
import { getValidationStylingProps } from '../../shared/style';
import useKeyboardNavigation from '../hooks/useKeyboardNavigation';
import useClearButton from '../hooks/useClearButton';
import useFocusHandlers from '../hooks/useFocusHandlers';
import ComboboxTag from './ComboboxTag';
import ControlButtons from './ControlButtons';
import { borderFocusWithinClass, borderFocusWithinVar, inputStyle } from './styles.ve.css';
import { generateBorderFocusWithin } from './style';
import { CONTROL_BUTTONS_WIDTH } from './ControlButtons/constants';
import { getInputDefaultValue } from './utils/getInputDefaultValue';
import { TriggerProps } from './types';

const Trigger = forwardRef<HTMLInputElement, TriggerProps>(
  (
    {
      placeholder,
      isError,
      isSuccess,
      disabled,
      defaultValue,
      hideClearButton,
      onBlur,
      onFocus,
      theme,
      dataTrackTag,
      dataTrackValue,
      ...rest
    },
    ref
  ) => {
    const { open } = usePopoverContext();
    const {
      setSearchValue,
      inputRef,
      isInitialMultiSelect,
      innerValue,
      searchValue,
      filteredMenuGroups,
      setCurrentFocusedElement,
      controlled,
      shouldFilterItems,
      updatedSelectedItems,
    } = useComboboxContext();
    const trackValue = useInputTrackValue({ dataTrackValue, value: updatedSelectedItems });
    const isDark = theme === 'dark';
    const borderFocusWithin = generateBorderFocusWithin({ isError, isSuccess, isDark });
    const isMultiSelect = isInitialMultiSelect.current;
    const containerRef = useRef<HTMLElement | null>(null);
    const { handleInputKeyDown, handleContainerKeyDown } = useKeyboardNavigation(updatedSelectedItems);
    const { showClearButton, onMouseEnter, onMouseLeave } = useClearButton(containerRef, hideClearButton);
    const { handleFocus, handleBlur } = useFocusHandlers(onBlur, onFocus);
    const inputDefault = useMemo(() => {
      const inputDefaultValue = getInputDefaultValue(
        isMultiSelect,
        controlled,
        defaultValue,
        innerValue,
        filteredMenuGroups
      );
      if (isNil(searchValue) && inputDefaultValue) {
        return inputDefaultValue;
      }
    }, [searchValue, isMultiSelect, controlled, defaultValue, innerValue, filteredMenuGroups]);

    useEffect(() => {
      if (open) {
        setCurrentFocusedElement(inputRef.current);
      }
    }, [open, setCurrentFocusedElement, inputRef]);

    useImperativeHandle<HTMLInputElement | null, HTMLInputElement | null>(ref, () => inputRef.current);
    return (
      <DropdownAnchor
        dataTrackTag={dataTrackTag}
        dataTrackValue={trackValue}
        fullWidth
        onFocus={handleFocus}
        onBlur={handleBlur}
        disabled={disabled}
        embed
      >
        <Stack
          role="combobox"
          width="100%"
          borderRadius="lg"
          paddingY="1.5"
          paddingX="3"
          justifyContent="spaceBetween"
          alignItems="center"
          borderWidth="sm"
          onClick={() => {
            setCurrentFocusedElement(inputRef?.current);
          }}
          onMouseEnter={onMouseEnter}
          onMouseLeave={onMouseLeave}
          {...getValidationStylingProps({ isError, isSuccess, disabled, open })}
          {...(isDark ? { borderColor: 'white_20', backgroundColor: 'white_10' } : undefined)}
          style={assignInlineVars({
            [borderFocusWithinVar]: tokens.colors[borderFocusWithin],
          })}
          className={borderFocusWithinClass}
          {...rest}
        >
          <Stack
            ref={containerRef}
            aria-hidden
            alignItems="center"
            wrap="wrap"
            gap="1"
            minHeight="32px"
            width="100%"
            maxWidth={`calc(100% - ${CONTROL_BUTTONS_WIDTH}px)`}
            onKeyDown={handleContainerKeyDown}
          >
            {updatedSelectedItems?.map(
              ({ value, groupName, children }) =>
                isMultiSelect && (
                  <ComboboxTag groupName={groupName} value={value} key={value}>
                    {children}
                  </ComboboxTag>
                )
            )}
            <Box
              as="input"
              ref={inputRef}
              className={classNames(inputStyle, utilityClasses.placeholder)}
              textOverflow="ellipsis"
              whiteSpace="nowrap"
              overflow="hidden"
              background="none"
              lineHeight="b_sm"
              fontSize="b_md"
              fontFamily="primary"
              color={isDark ? 'grey_700' : undefined}
              flex={1}
              onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
                shouldFilterItems.current = false;
                setSearchValue(event.target.value);
              }}
              value={inputDefault || searchValue}
              placeholder={placeholder}
              onKeyDown={handleInputKeyDown}
              tabIndex={disabled ? -1 : 0}
            />
          </Stack>
          <ControlButtons showClearButton={showClearButton} disabled={disabled} />
        </Stack>
      </DropdownAnchor>
    );
  }
);

Trigger.displayName = 'Trigger';
export default Trigger;
