import { isEmpty, isNil } from 'lodash';
import { useDropdownContext } from '@fiverr-private/dropdown';
import useComboboxContext from '../useComboboxContext';
import { removeSelectedTag } from '../../Trigger/utils/removeSelectedTag';

export const handleTagsNavigation = ({ direction, inputRef, setCurrentFocusedElement, currentFocusedElement }) => {
    let newFocusedTag: Element | null = null;
    if ((!currentFocusedElement || currentFocusedElement.tagName === 'input') && inputRef.current) {
        newFocusedTag =
            direction === 'left' ? inputRef.current.previousElementSibling : inputRef.current.nextElementSibling;
    } else if (currentFocusedElement.tagName !== 'input') {
        newFocusedTag =
            direction === 'left'
                ? currentFocusedElement.previousElementSibling
                : currentFocusedElement.nextElementSibling;
    }
    if (newFocusedTag) {
        setCurrentFocusedElement(newFocusedTag);
    }
};

const useKeyboardNavigation = (selectedItems) => {
    const {
        popoverContext: { setOpen },
    } = useDropdownContext();
    const focusInput = () => {
        setCurrentFocusedElement(inputRef.current);
    };
    const clearAndFocusInput = () => {
        setInnerValue({});
        setSearchValue('');
        focusInput();
    };

    const {
        inputRef,
        isInitialMultiSelect,
        setCurrentFocusedElement,
        currentFocusedElement,
        setInnerValue,
        searchValue,
        innerValue,
        setSearchValue,
    } = useComboboxContext();
    const isMultiSelect = isInitialMultiSelect.current;

    const handleInputKeyDown = ({
        currentTarget: { selectionStart, selectionEnd, value },
        key,
        ctrlKey,
        metaKey,
    }: React.KeyboardEvent<HTMLInputElement>) => {
        const isDeleteKey = key === 'Backspace' || key === 'Delete';
        const isFullTextSelection = !isNil(value) && selectionStart === 0 && selectionEnd === value.length;
        const isValidKey = /^[a-zA-Z0-9]$/.test(key);
        const isCopyAction = (ctrlKey || metaKey) && key.toLowerCase() === 'c';

        if (isDeleteKey) {
            if (isEmpty(searchValue) && !isEmpty(selectedItems) && isMultiSelect) {
                const { value, groupName } = selectedItems[selectedItems.length - 1];
                setInnerValue(removeSelectedTag(innerValue, { tagValue: value, groupName }));
                focusInput();
            } else if (
                (!isNil(value) &&
                    value.length <= 1 &&
                    (!isEmpty(selectedItems) || !isEmpty(innerValue)) &&
                    !isMultiSelect) ||
                (isFullTextSelection && !isMultiSelect)
            ) {
                clearAndFocusInput();
            }
        }

        if (isFullTextSelection && !isMultiSelect && isValidKey && !isCopyAction) {
            clearAndFocusInput();
        }
        if (key === 'Tab') {
            focusInput();
        }
    };

    const handleContainerKeyDown = ({ key }: React.KeyboardEvent<HTMLInputElement>) => {
        const isDeleteKey = key === 'Backspace' || key === 'Delete';

        if (isEmpty(searchValue) && !isEmpty(selectedItems) && isMultiSelect) {
            if (key === 'ArrowLeft' || key === 'ArrowRight') {
                setOpen(false);
                handleTagsNavigation({
                    direction: key === 'ArrowLeft' ? 'left' : 'right',
                    inputRef,
                    setCurrentFocusedElement,
                    currentFocusedElement,
                });
            }
        }
        if (key === 'Tab') {
            focusInput();
        }
        const isValidKey = /^[a-zA-Z0-9]$/.test(key);
        if (isValidKey || (isDeleteKey && searchValue?.length)) {
            setOpen(true);
        }
    };

    return { handleContainerKeyDown, handleInputKeyDown };
};
export default useKeyboardNavigation;
