import React, { useRef } from 'react';
import { Tag, TagCloseIcon } from '@fiverr-private/data_display';
import { translate } from '@fiverr-private/i18n-react';
import { Text } from '@fiverr-private/typography';
import { getOptionText } from '../../utils';
import useComboboxContext from '../../hooks/useComboboxContext';
import { MenuItemExpanded } from '../../types';
import { removeSelectedTag } from '../utils/removeSelectedTag';

const ComboboxTag = ({ children, value, groupName }: MenuItemExpanded) => {
  const tagRef = useRef<HTMLElement>(null);
  const { setInnerValue, inputRef, innerValue, setCurrentFocusedElement, theme } = useComboboxContext();
  const text = getOptionText(children);

  return (
    <Tag
      theme={theme}
      ref={tagRef}
      key={value}
      onClick={(e) => {
        setInnerValue(removeSelectedTag(innerValue, { tagValue: value, groupName }));
        e.stopPropagation();
        e.preventDefault();
      }}
      onKeyDown={(e) => {
        if (e.key === 'Backspace') {
          e.stopPropagation();
          setInnerValue(removeSelectedTag(innerValue, { tagValue: value, groupName }));
          setCurrentFocusedElement(inputRef.current);
        }
        e.preventDefault();
      }}
      tabIndex={-1}
      ariaLabel={translate<string>('forms.combobox.comboboxTag.removeItem', { params: { item: text } })}
      size="sm"
      maxWidth="100%"
      dataTrackTag="combobox_tag"
      dataTrackValue={value?.toString()}
    >
      <Text
        as="span"
        whiteSpace="nowrap"
        overflow="hidden"
        textOverflow="ellipsis"
        width="100%"
        maxWidth="100%"
        color="inherit"
      >
        {text}
      </Text>
      <TagCloseIcon />
    </Tag>
  );
};

export default ComboboxTag;
