import { Children } from 'react';
import { isNil } from 'lodash';
import { MenuItemProps } from '@fiverr-private/dropdown';
import { getOptionText } from '../../utils';
import { MenuItemElement } from '../../types';

const getSelectedItemByValue = (menuItems, groupSelectedValues): MenuItemProps | null => {
    let selectedItemProps: MenuItemProps | null = null;
    if (!groupSelectedValues) {
        return selectedItemProps;
    }

    Children.forEach(menuItems, (child) => {
        if ((child as MenuItemElement).props.value?.toString() === groupSelectedValues) {
            selectedItemProps = child.props;
        }
    });

    return selectedItemProps;
};

export const getInputDefaultValue = (isMultiSelect, controlled, defaultValue, values, children) => {
    if (!isMultiSelect && (controlled || defaultValue)) {
        const currentValue = controlled ? values : defaultValue;
        const selectedItem = getSelectedItemByValue(children, currentValue.item);
        if (!isNil(selectedItem)) {
            return getOptionText(selectedItem.children);
        }
    }
};
