import React from 'react';
import { MenuItem } from '@fiverr-private/dropdown';
import { useInputTrackValue } from '@fiverr-private/inputs';
import { getOptionText } from '../utils';
import useComboboxContext from '../hooks/useComboboxContext';
import { ComboboxOptionProps } from './types';

const ComboboxOption = ({
  children,
  value,
  disabled,
  onClick,
  dataTrackTag = 'combobox_option',
  dataTrackValue,
}: ComboboxOptionProps) => {
  const trackValue = useInputTrackValue({ dataTrackValue, value });
  const { setSearchValue, inputRef, isInitialMultiSelect, setCurrentFocusedElement, shouldFilterItems } =
    useComboboxContext();

  const handleClick = (e) => {
    if (!isInitialMultiSelect.current) {
      setSearchValue(getOptionText(children));
      shouldFilterItems.current = true;
    } else {
      setSearchValue('');
    }
    setCurrentFocusedElement(inputRef.current);
    onClick?.(e);
  };

  return (
    <MenuItem
      dataTrackTag={dataTrackTag}
      dataTrackValue={trackValue}
      value={value}
      disabled={disabled}
      onClick={handleClick}
      selectable
    >
      {children}
    </MenuItem>
  );
};

ComboboxOption.displayName = 'ComboboxOption';
export default ComboboxOption;
