import { type Types } from '@fiverr-private/theme';
import { formsTokenColors } from '@fiverr-private/inputs';
import { SelectProps } from '../Select/types';

interface GetBorderColor {
    disabled: SelectProps['disabled'];
    isError: SelectProps['isError'];
    isSuccess: SelectProps['isSuccess'];
    open: boolean;
}

export const getBorderColor = ({
    isError,
    isSuccess,
    disabled,
    open,
}: GetBorderColor): {
    outlineColor?: Types.FocusesOutlineColorType;
    borderColor: Types.SelectorBorderColorsType;
} => {
    if (isError) {
        return {
            borderColor: 'validationError',
            outlineColor: 'validationError',
        };
    } else if (isSuccess) {
        return {
            borderColor: 'validationSuccess',
            outlineColor: 'validationSuccess',
        };
    } else if (disabled) {
        return {
            borderColor: formsTokenColors.borderColor,
        };
    } else {
        return {
            borderColor: {
                default: open ? formsTokenColors.interactiveColor : formsTokenColors.borderColor,
                hover: formsTokenColors.interactiveColor,
                focus: formsTokenColors.interactiveColor,
            },
            outlineColor: formsTokenColors.interactiveColor,
        };
    }
};

export const getOutlineProps = ({
    open,
    outlineColor,
}: {
    open: boolean;
    outlineColor?: Types.FocusesOutlineColorType;
}): Types.ContainerProps => ({
    outlineStyle: open
        ? 'solid'
        : {
              focus: 'solid',
              focusVisible: 'solid',
              focusWithin: 'solid',
          },
    outlineWidth: open
        ? 'sm'
        : {
              focus: 'sm',
              focusVisible: 'sm',
              focusWithin: 'sm',
          },
    outlineColor,
});

export const getValidationStylingProps = ({
    isError,
    isSuccess,
    disabled,
    open,
}): Omit<Types.ContainerProps, 'display'> => {
    const { borderColor, outlineColor } = getBorderColor({ isError, isSuccess, disabled, open });
    const outlineProps = getOutlineProps({ open, outlineColor });
    return {
        borderColor,
        ...outlineProps,
        backgroundColor: disabled ? formsTokenColors.disabledFieldBackgroundColor : 'background',
        color: disabled ? formsTokenColors.disabledColor : formsTokenColors.color,
        pointerEvents: disabled ? 'none' : undefined,
    };
};
