import { isEmpty } from 'lodash';
import { useEffect } from 'react';
import { usePopoverContext } from '@fiverr-private/popover';
import { getSelectedItemByText } from '../../utils';
import useComboboxContext from '../useComboboxContext';
import { TriggerProps } from '../../Trigger/types';

const useFocusHandlers = (onBlur: TriggerProps['onBlur'], onFocus: TriggerProps['onFocus']) => {
    const { open } = usePopoverContext();
    const {
        setSearchValue,
        inputRef,
        innerValue,
        filteredMenuGroups,
        currentFocusedElement,
        setCurrentFocusedElement,
        shouldFilterItems,
        isInitialMultiSelect,
    } = useComboboxContext();

    useEffect(() => {
        if (currentFocusedElement) {
            currentFocusedElement?.focus();
        }
    }, [currentFocusedElement, innerValue, open]);

    const handleFocus = (e) => {
        if (!currentFocusedElement) {
            setCurrentFocusedElement(inputRef?.current);
        } else {
            setCurrentFocusedElement(currentFocusedElement);
        }
        onFocus?.(e);
    };

    const handleBlur = (e) => {
        if (isInitialMultiSelect.current) {
            setSearchValue('');
        } else if (!isEmpty(innerValue)) {
            setSearchValue(getSelectedItemByText(filteredMenuGroups, innerValue));
        }
        shouldFilterItems.current = true;
        onBlur?.(e);
    };
    return { handleBlur, handleFocus };
};

export default useFocusHandlers;
