import React from 'react';
import type { Values } from '@fiverr-private/dropdown';
import { getFilteredChildren } from '../../utils';
import type { MenuItemExpanded, ThemeType } from '../../types';

export interface IComboboxContext {
    searchValue?: string;
    setSearchValue: React.Dispatch<React.SetStateAction<string | undefined>>;
    isInitialMultiSelect: React.MutableRefObject<boolean | null>;
    inputRef: React.RefObject<HTMLInputElement>;
    filteredMenuGroups: ReturnType<typeof getFilteredChildren>;
    setInnerValue: (newValues: Values) => void;
    innerValue: Values;
    currentFocusedElement: HTMLElement | null;
    setCurrentFocusedElement: React.Dispatch<React.SetStateAction<HTMLElement | null>>;
    shouldFilterItems: React.MutableRefObject<boolean>;
    updatedSelectedItems: MenuItemExpanded[];
    controlled: boolean;
    hasMultipleGroups: boolean;
    theme: ThemeType;
}

export const ComboboxContext = React.createContext<IComboboxContext | null>(null);

const useComboboxContext = () => {
    const context = React.useContext(ComboboxContext);

    if (!context) {
        throw new Error('useComboboxContext must be used within a ComboboxProvider');
    }

    return context;
};

export default useComboboxContext;
