import { userEvent, within } from '@storybook/test';

interface Elements {
    trigger: HTMLElement;
    clearButton: Element | null;
    items: () => Promise<HTMLElement[]>;
    canvas: ReturnType<typeof within>;
}

export const clickElement = async (
    element: Parameters<typeof userEvent.click>['0'],
    options: Parameters<typeof userEvent.click>['1'] = {}
) => {
    await userEvent.click(element, options);
};

export const keyboardEvent = async (eventName, times = 1, options: Parameters<typeof userEvent.keyboard>['1'] = {}) => {
    const promisesToAwait: any = [];

    for (let i = 0; i < times; i++) {
        promisesToAwait.push(await userEvent.keyboard(eventName, options));
    }

    await Promise.all(promisesToAwait);
};

export const selectItemByKeyboard = async (
    eventName: '[ArrowDown]' | '[ArrowUp]',
    navigateTimes = 1,
    selectTimes = 1
) => {
    for (let i = 0; i < selectTimes; i++) {
        await keyboardEvent(eventName, navigateTimes);
        await keyboardEvent('[Enter]');
    }
};

export const openDropdown = async (trigger: Parameters<typeof userEvent.click>['0']) => {
    await clickElement(trigger, { delay: 400 });
};

export const selectItemByClick = async (element: Element) => {
    await clickElement(element);
};

export const getElements = async (canvasElement: HTMLElement): Promise<Elements> => {
    const canvas = within(canvasElement);
    const trigger = await canvas.findByRole('combobox');
    const clearButton = trigger.querySelector?.('[aria-label="Clear"]');
    const items = async () => canvas.findAllByRole('listitem', { hidden: true });

    return {
        trigger,
        clearButton,
        items,
        canvas,
    };
};

