import { isArray, isEmpty, isNil, omitBy } from 'lodash';
import type { ItemValue, Values } from '@fiverr-private/dropdown';

export const removeSelectedTag = (items: Values, { tagValue, groupName }): Values => {
    const groupItems = isArray(items[groupName])
        ? (items[groupName] as ItemValue[])?.filter((val) => val !== tagValue)
        : null;

    const updatedItems = {
        ...items,
        [groupName]: groupItems,
    };

    return omitBy(updatedItems, (v) => isNil(v) || isEmpty(v));
};
